function cekstatuskantong($status, $stattempat, $sah, $statusrelease)
{
    $yhfhqrozgtk = "status";
    $mrgixxjzesyn = "resulstatus";
    $resulstatus = "";
    $grgojcypx = "stattempat";
    $vyjkxrobbu = "resulstatus";
    $oxdglcoghz = "resulstatus";
    $lgypocfr = "resulstatus";
    $resulstatus = "resulstatus";
    $gtgxqptlvest = "resulstatus";
    $resulstatus = "resulstatus";
    $cvqlifprgnd = "stattempat";
    $stattempat = "stattempat";

    switch (${$yhfhqrozgtk}) {
        case "0":
            $resulstatus = "Kosong";
            if ($stattempat == null) {
                $resulstatus = "Kosong di logistik";
            }
            if (${$grgojcypx} == "0") {
                ${$mrgixxjzesyn} = "Kosong di Logistik";
            }
            if (${$cvqlifprgnd} == "1") {
                $resulstatus = "Kosong di Aftap";
            }
            break;
        case "1":
            if ($sah == "1") {
                $jftgtfei = "resulstatus";
                ${$jftgtfei} = "Karantina";
            } else {
                $resulstatus = "resulstatus";
                $resulstatus = "Belum disahkan";
            }
            break;
        case "2":
            switch ($statusrelease) {
                case "0":
                    $resulstatus = "Sehat, belum release";
                    break;
                case "1":
                    $resulstatus = "Sehat, Lulus";
                    break;
                case "2":
                    $resulstatus = "Sehat, Tidak Lulus";
                    break;
                case "3":
                    $resulstatus = "Sehat, Lulus (Catatan)";
                    break;
                default:
                    $resulstatus = "Sehat, belum release";
                    break;
            }
            break;
        case "3":
            ${$oxdglcoghz} = "Keluar";
            break;
        case "4":
            ${$gtgxqptlvest} = "Rusak";
            break;
        case "5":
            ${$vyjkxrobbu} = "Rusak-Gagal";
            break;
        case "6":
            $resulstatus = "Dimusnahkan";
            break;
        case "7":
            ${$lgypocfr} = "Reaktif";
            break;
        case "8":
            $resulstatus = "Uji Mutu (QC)";
            break;
        default:
            $resulstatus = "Musnah";
    }
    return $resulstatus;
}

