function datalogistik($nokantong)
{
    $kantongke = "kantongke";
    $jeniskantong = "jeniskantong";
    $etswdykc = "qrykantong";
    global $dbi;
    $glppfhpvh = "qrykantong";
    $jeniskantong = "jeniskantong";
    $hyeanihfuofy = "posisikantong";
    $wedudivu = "posisikantong";
    $fhasil = "";
    $dqekykdygg = "dbi";
    $kantongke = strtoupper(substr($nokantong, -1));
    $yiekwnpbdd = "jeniskantong";
    $clyvlmdnsed = "fhasil";
    $qrykantong = "qrykantong";
    $lgefpjedqn = "qrykantong";
    $no_kantonga = substr_replace($nokantong, "A", -1, 1);
    $vfdafqpvyhsg = "jeniskantong";
    $qmgquqpihtn = "posisikantong";

    switch ($kantongke) {
        case "A":
            $posisikantong = "Kantong Utama";
            break;
        case "B":
            $posisikantong = "Kantong Satelite 1";
            break;
        case "C":
            ${$wedudivu} = "Kantong Satelite 2";
            break;
        case "D":
            ${$qmgquqpihtn} = "Kantong Satelite 3";
            break;
        case "E":
            $posisikantong = "Kantong Satelite 4";
            break;
        case "F":
            $posisikantong = "Kantong Satelite 5";
            break;
        case "G":
            $posisikantong = "Kantong Satelite 6";
            break;
        case "H":
            ${$hyeanihfuofy} = "Kantong Satelite 7";
            break;
        default:
            $posisikantong = "";
    }

    ${$lgefpjedqn} = mysqli_fetch_assoc(mysqli_query(${$dqekykdygg}, "SELECT * FROM `stokkantong` WHERE upper(`noKantong`)=upper('$no_kantonga');"));

    switch (${$glppfhpvh}["jenis"]) {
        case "1":
            $jeniskantong = "Single";
            break;
        case "2":
            $jeniskantong = "Double";
            break;
        case "3":
            $jeniskantong = "Triple";
            break;
        case "4":
            ${$yiekwnpbdd} = "Quadruple";
            break;
        case "5":
            $jeniskantong = "Quadruple T&B";
            break;
        case "6":
            $jeniskantong = "Pediatrik";
            break;
        default:
            ${$vfdafqpvyhsg} = "";
    }

    ${$clyvlmdnsed} .= "\n <div class=\"row\">\n <div class=\"col-xs-12\">\n <div class=\"panel w3-border-theme\">\n <div class=\"panel-heading w3-theme-d4 w3-card-4\" style=\"height:50px;font-size:150%;font-weight:bold;\">Data Logistik</div>\n <div class=\"panel-body w3-card-4\">\n <div class=\"col-xs-12 col-sm-6\">\n <div class=\"table-responsive\">\n <table class=\"table table-responsive table-striped table-bordered\">\n <tr><td>Jenis Kantong</td> <td class=\"w3-hover-theme\">" . $jeniskantong . "</td></tr>\n <tr><td>Merk Kantong</td> <td class=\"w3-hover-theme\">" . $qrykantong["merk"] . " " . $qrykantong["volumeasal"] . "ml</td></tr>\n <tr><td>Posisi Kantong</td> <td class=\"w3-hover-theme\">" . $posisikantong . "</td></tr>\n <tr><td>Nomor Lot</td> <td class=\"w3-hover-theme\">" . ${$etswdykc}["nolot_ktg"] . "</tr>\n </table>\n </div>\n </div>\n <div class=\"col-xs-12 col-sm-6\">\n <div class=\"table-responsive\">\n <table class=\"table table-responsive table-striped table-bordered\">\n <tr><td>Tgl Input/Barcode </td> <td class=\"w3-hover-theme\">" . $qrykantong["tglTerima"] . "</td></tr>\n <tr><td>Tgl Mutasi ke Pengambilan</td> <td class=\"w3-hover-theme\">" . $qrykantong["tglmutasi"] . "</td></tr>\n <tr><td>Tgl ED Kantong</td> <td class=\"w3-hover-theme\">" . $qrykantong["kadaluwarsa_ktg"] . "</td></tr>\n </table>\n </div>\n </div>\n </div>\n </div>\n </div>\n </div>";

    return $fhasil;
}

function datapengambilan($nokantong, $modul = 'default')
{
    global $dbi;

    $output = '';

    // Ambil data transaksi pengambilan (aftap)
    $qAftap = mysqli_query($dbi, "SELECT * FROM htransaksi WHERE NoKantong = '".substr($nokantong, 0, -1)."'");
    if (mysqli_num_rows($qAftap) == 0) {
        return "<div class='alert alert-danger'>Data pengambilan untuk kantong $nokantong tidak ditemukan.</div>";
    }

    $aftap = mysqli_fetch_assoc($qAftap);

    // Tentukan asal donor
    $asal = ($aftap['NoTrans'][0] === 'M') ? 'Mobile Unit' : 'Dalam Gedung';

    // Format hemoglobin
    $hb_display = $aftap['Hb'] ? $aftap['Hb']." gr/dl" : '-';
    if (!$aftap['Hb'] || $aftap['Hb'] == '0') {
        switch ($aftap['jumHB']) {
            case '1': $hb_display = 'Tenggelam';
                break;
            case '2': $hb_display = 'Melayang';
                break;
            case '3': $hb_display = 'Mengapung';
                break;
            default:  $hb_display = '-';
        }
    }

    // Cara ambil
    $caraAmbil = match($aftap['caraAmbil']) {
        '0' => 'Donor Biasa',
        '1' => 'Tromboferesis',
        '2' => 'Leukoferesis',
        '3' => 'Plasmaferesis',
        '4' => 'Eritroferesis',
        '5' => 'Plebotomi',
        default => '-'
    };

    // Status pengambilan
    $statusAftap = match($aftap['Pengambilan']) {
        '0' => 'Berhasil',
        '1' => 'Batal',
        '2' => 'Gagal',
        default => '-'
    };

    // Data stok kantong terkait
    $qStok = mysqli_query($dbi, "SELECT * FROM stokkantong WHERE UPPER(noKantong) = UPPER('".substr($nokantong, 0, -1)."')");
    $stok  = mysqli_fetch_assoc($qStok);
    $lamaAftap = $stok['lama_pengambilan'] ?? '-';

    // Dokter pemeriksa
    $qDokter = mysqli_query($dbi, "SELECT Nama FROM dokter_periksa WHERE kode = '{$aftap['NamaDokter']}'");
    $dokter  = mysqli_fetch_assoc($qDokter)['Nama'] ?? '-';

    // =================================================================
    // Tampilan HTML - Bagian Pengambilan
    // =================================================================
    $output .= '
    <div class="row">
        <div class="col-xs-12">
            <div class="panel w3-border-theme w3-card-4">
                <div class="panel-heading w3-theme-d4 w3-card-4" style="height:50px;font-size:150%;font-weight:bold;">
                    Data Pengambilan
                </div>
                <div class="panel-body w3-card-4">
                    <div class="col-xs-12 col-sm-6">
                        <div class="table-responsive">
                            <table class="table table-responsive table-striped table-bordered">
                                <tr><td>No. Transaksi</td><td class="w3-hover-theme">'.$aftap['NoTrans'].'</td></tr>
                                <tr><td>Tempat Pengambilan</td><td class="w3-hover-theme">'.$asal.' '.$aftap['Instansi'].'</td></tr>
                                <tr><td>Tgl & Waktu Registrasi</td><td class="w3-hover-theme">'.$aftap['Tgl'].'</td></tr>
                                <tr><td>Tensi</td><td class="w3-hover-theme">'.$aftap['tensi'].' mmHg</td></tr>
                                <tr><td>Nadi</td><td class="w3-hover-theme">'.$aftap['nadi'].' bpm</td></tr>
                                <tr><td>Suhu</td><td class="w3-hover-theme">'.$aftap['suhu'].'<sup>o</sup>C</td></tr>
                                <tr><td>Berat Badan</td><td class="w3-hover-theme">'.$aftap['beratBadan'].' kg</td></tr>
                                <tr><td>Hemoglobin</td><td class="w3-hover-theme">'.$hb_display.'</td></tr>
                                <tr><td>Golongan Darah</td><td class="w3-hover-theme">'.$aftap['gol_darah'].' Rh '.$aftap['rhesus'].'</td></tr>
                            </table>
                        </div>
                    </div>
                    <div class="col-xs-12 col-sm-6">
                        <div class="table-responsive">
                            <table class="table table-responsive table-striped table-bordered">
                                <tr><td>Jenis Pengambilan</td><td class="w3-hover-theme">'.$caraAmbil.'</td></tr>
                                <tr><td>Tgl & Waktu Pengambilan</td><td class="w3-hover-theme">'.$stok['tgl_Aftap'].'</td></tr>
                                <tr><td>Volume Pengambilan</td><td class="w3-hover-theme">'.$aftap['volumekantong'].' ml</td></tr>
                                <tr><td>Lama Pengambilan</td><td class="w3-hover-theme">'.$lamaAftap.' menit</td></tr>
                                <tr><td>Status Pengambilan</td><td class="w3-hover-theme">'.$statusAftap.'</td></tr>
                                <tr><td>Petugas Tensi</td><td class="w3-hover-theme">'.$aftap['petugasTensi'].'</td></tr>
                                <tr><td>Petugas Anamnesa</td><td class="w3-hover-theme">'.$dokter.'</td></tr>
                                <tr><td>Petugas HB</td><td class="w3-hover-theme">'.$aftap['petugasHB'].'</td></tr>
                                <tr><td>Petugas Aftap</td><td class="w3-hover-theme">'.$aftap['petugas'].'</td></tr>
                                <tr><td>Petugas Input data</td><td class="w3-hover-theme">'.$aftap['user'].'</td></tr>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>';

    // =================================================================
    // Data Pendonor (hanya ditampilkan jika level/modul tertentu)
    // =================================================================
    $tampilPendonor = in_array($modul, ['admin','kasir','p2d2s','pimpinan','konseling','aftap']);

    if ($tampilPendonor) {
        $qPendonor = mysqli_query($dbi, "SELECT * FROM pendonor WHERE Kode = '{$aftap['KodePendonor']}'");
        $pendonor  = mysqli_fetch_assoc($qPendonor);

        $jk         = ($aftap['jk'] == '1') ? 'Perempuan' : 'Laki-laki';
        $statusDonor = ($aftap['donorbaru'] == '0') ? 'Donor Baru' : 'Donor Ulang';
        $jenisDonor = ($aftap['JenisDonor'] == '1') ? 'Donor Pengganti' : 'Donor Sukarela';

        $output .= '
        <div class="row">
            <div class="col-xs-12">
                <div class="panel w3-border-theme w3-card-4">
                    <div class="panel-heading w3-theme-d4 w3-card-4" style="height:50px;font-size:150%;font-weight:bold;">
                        Data Pendonor
                    </div>
                    <div class="panel-body w3-card-4">
                        <div class="col-xs-12 col-sm-6">
                            <div class="table-responsive">
                                <table class="table table-responsive table-striped table-bordered">
                                    <tr><td>Kode Pendonor</td><td class="w3-hover-theme">'.$aftap['KodePendonor'].'</td></tr>
                                    <tr><td>Jenis Kelamin</td><td class="w3-hover-theme">'.$jk.'</td></tr>
                                    <tr><td>Jenis Donor</td><td class="w3-hover-theme">'.$jenisDonor.'</td></tr>
                                    <tr><td>Status Donor</td><td class="w3-hover-theme">'.$statusDonor.'</td></tr>
                                    <tr><td>Umur Donor</td><td class="w3-hover-theme">'.$aftap['umur'].' tahun</td></tr>
