                                </table>
                            </div>
                        </div>
                        <div class="col-xs-12 col-sm-6">
                            <div class="table-responsive">
                                <table class="table table-responsive table-striped table-bordered">
                                    <tr><td>Nama</td><td class="w3-hover-theme">'.$pendonor['Nama'].'</td></tr>
                                    <tr><td>NIK</td><td class="w3-hover-theme">'.$pendonor['NoKTP'].'</td></tr>
                                    <tr><td>Alamat</td><td class="w3-hover-theme">'.$pendonor['Alamat'].' '.$pendonor['kelurahan'].' '.$pendonor['kecamatan'].' '.$pendonor['KodePos'].'</td></tr>
                                    <tr><td>Wilayah</td><td class="w3-hover-theme">'.$pendonor['wilayah'].'</td></tr>
                                    <tr><td>Tempat Lahir</td><td class="w3-hover-theme">'.$pendonor['TempatLhr'].'</td></tr>
                                    <tr><td>Tgl Lahir</td><td class="w3-hover-theme">'.$pendonor['TglLhr'].'</td></tr>
                                    <tr><td>Donasi</td><td class="w3-hover-theme">'.$pendonor['jumDonor'].' Kali</td></tr>
                                    <tr><td>Nomor HP</td><td class="w3-hover-theme">'.$pendonor['telp2'].'</td></tr>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>';
    }

    return $output;
}

